    var normalizedName = msg.deviceName.replace(/\s+/g, '').toUpperCase();

    // Check if this is COMP2 (handles SPT or SPLIT)
    var comp2Match = normalizedName.match(/^((?:SPT|SPLIT)\d+):?COMP2$/);
    if (comp2Match) {
        var sptId = comp2Match[1]; // e.g., "SPT3" or "SPLIT7"

        // Get compressores list
        var compressores = flow.get('compressores') || {};

        // Look for COMP1 with same SPT - normalize keys to compare
        var comp1IsOn = false;
        var comp1Found = false;
        for (var key in compressores) {
            if (compressores.hasOwnProperty(key)) {
                var normalizedKey = key.replace(/\s+/g, '').toUpperCase();
                if (normalizedKey === sptId + ':COMP1' || normalizedKey === sptId + 'COMP1') {
                    comp1IsOn = compressores[key];
                    comp1Found = true;
                    break;
                }
            }
        }

        if (!comp1Found) {
            node.warn('Ignoring ' + msg.deviceName + '. COMP1 not found for ' + sptId);
            return null;
        }

        if (!comp1IsOn) {
            node.warn('Ignoring ' + msg.deviceName + '. COMP1 must be turned on first.');
            return null;
        }
    }
}

