function parseUPSData(msg) {
    let curRunData = {};
    let sysstat = [0, 0];

    // Process the array of two objects
    msg.payload.forEach(item => {
        if (item.XmlDataFile.CurRunData) {
            const dataString = item.XmlDataFile.CurRunData[0];
            const pairs = dataString.split('|');
            pairs.forEach(pair => {
                const [key, value] = pair.split(':');
                curRunData[key] = value;
            });
        }
        if (item.XmlDataFile.SYSSTAT) {
            sysstat = item.XmlDataFile.SYSSTAT[0].split('|').map(Number);
        }
    });

    function getValue(id) {
        return curRunData[id] || 'N/A';
    }

    function getStatus(id) {
        return curRunData[id] === '1';
    }

    const result = {
        batteryVoltage: getValue('29'),
        inputVoltage: {
            phase1: getValue('35'),
            phase2: getValue('39'),
            phase3: getValue('43')
        },
        outputVoltage: {
            phase1: getValue('49'),
            phase2: getValue('53'),
            phase3: getValue('57')
        },
        bypassVoltage: {
            phase1: getValue('63'),
            phase2: getValue('66'),
            phase3: getValue('69')
        },
        outputLoad: {
            phase1: getValue('52'),
            phase2: getValue('56'),
            phase3: getValue('60'),
            total: getValue('73')
        },
        batteryCapacity: getValue('74'),
        upsTemperature: getValue('75'),
        remainingBackupTime: getValue('26'),
        status: {
            overTemperature: getStatus('32784'),
            inputFault: getStatus('32785'),
            outputFault: getStatus('32786'),
            overload: getStatus('32787'),
            bypassFault: getStatus('32788'),
            upsShutdown: getStatus('32790'),
            batteryFault: getStatus('32800'),
            batteryVoltageLow: getStatus('32801'),
            phaseLoss: {
                A: getStatus('32864'),
                B: getStatus('32865'),
                C: getStatus('32866')
            },
            generalFault: getStatus('32795'),
            instantShutdown: getStatus('32798'),
            testIndications: getStatus('32804'),
            runningStatus: getValue('32802') === '0' ? 'Invert' : 'Bypass',
            deviceOffline: getStatus('32799')
        },
        rawSYSSTAT: sysstat.join('|')
    };

    msg.payload = result;
    return msg;
}

