msg.payload=JSON.stringify(a,null,2); msg.filename='/tmp/feriados.json'; return msg;

let a=[]; try{ a=JSON.parse(msg.payload||'[]'); }catch(e){}
if(!Array.isArray(a)) a=[];
global.set('feriados',a);
return {topic:'feriadosload', payload:a};

// Prepara a mensagem de e-mail do alarme. Ligue a saída no SEU nó de e-mail (SMTP configurado).
// Defina o destinatário aqui ou no nó de e-mail:
msg.to = msg.to || flow.get('alarm_email_to') || '';   // ex.: 'voce@empresa.com'
return msg;

const cat=global.get('catalog');
if(cat && (cat.deviceIds || cat.acs || cat.meters)) { return {topic:'catalog', payload:cat}; }
return null;

// cacheia o ÚLTIMO status de cada equipamento e repassa adiante
const m=msg;
if(m && m.topic && m.payload){
  const TOPICS=['conswatts','telemetry','temp','status'];
  if(TOPICS.indexOf(m.topic)>=0){
    const p=m.payload;
    const id=(p.id!=null)?p.id:((p.itemId!=null)?p.itemId:p.point);
    if(id!=null){
      const c=global.get('uiCache')||{};
      c[m.topic+':'+id]={topic:m.topic,payload:p};
      global.set('uiCache',c);
    }
  }
}
return msg;

// no 'ready' (refresh/reconexão) reenvia todos os últimos status cacheados
const c=global.get('uiCache')||{};
const out=Object.keys(c).map(function(k){ return {topic:c[k].topic, payload:c[k].payload}; });
return [out];
